"""
Invoice export to the billing API (written against pydantic 1.10).

Provides:
  - export_invoice(data: dict) -> str
"""
from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, List

from pydantic import BaseModel, ValidationError, validator
from pydantic.json import ENCODERS_BY_TYPE


def _to_utc_datetime(value: datetime) -> datetime:
    """Convert naive datetimes to UTC; convert aware datetimes to UTC."""
    if value.tzinfo is None or value.tzinfo.utcoffset(value) is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def _format_issued_at_utc_z(dt: datetime) -> str:
    """YYYY-MM-DDTHH:MM:SSZ in UTC (second precision)."""
    dt_utc = _to_utc_datetime(dt)
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")


def _quantize_2dp(d: Decimal) -> Decimal:
    # Convert to exactly 2 decimal places (billing API expects that exact form)
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("quantity")
    def quantity_min_1(cls, v: int) -> int:
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def unit_price_non_negative(cls, v: Any) -> Any:
        # Let pydantic parse into Decimal; then validate constraints in a second validator.
        return v

    @validator("unit_price")
    def unit_price_constraints(cls, v: Decimal) -> Decimal:
        if v < 0:
            raise ValueError("unit_price must be >= 0")
        # Ensure it is representable with at most 2 decimal places; then quantize.
        quantized = _quantize_2dp(v)
        if v != quantized:
            # Reject inputs with more than 2 decimals to avoid silently rounding.
            raise ValueError("unit_price must have at most 2 decimal places")
        return quantized


class InvoiceExportModel(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    class Config:
        # We'll custom-encode issued_at with required format for the billing API.
        json_encoders = {
            datetime: _format_issued_at_utc_z,
            Decimal: lambda d: f"{_quantize_2dp(d):.2f}",
        }

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v: Any) -> Any:
        # pydantic parses ISO strings already; we only need to ensure timezone handling later.
        return v

    @validator("issued_at")
    def issued_at_to_utc(cls, v: datetime) -> datetime:
        return _to_utc_datetime(v)

    def export_dict(self) -> dict:
        total = sum((line.quantity * line.unit_price for line in self.lines), Decimal("0"))
        total_q = _quantize_2dp(total)

        return {
            "number": self.number,
            "issued_at": _format_issued_at_utc_z(self.issued_at),
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    # Exactly two decimals as a string
                    "unit_price": f"{_quantize_2dp(line.unit_price):.2f}",
                }
                for line in self.lines
            ],
            # Total is required as a string with exactly two decimals
            "total": f"{total_q:.2f}",
        }


def export_invoice(data: dict) -> str:
    """
    Validate invoice input and return billing-API JSON text.

    Expected input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive values treated as UTC)
      - lines: list of dicts with
          - sku (str)
          - quantity (int >= 1)
          - unit_price (Decimal >= 0; provided as str/int/float)

    Output JSON:
      - number
      - issued_at: "YYYY-MM-DDTHH:MM:SSZ"
      - lines: [{"sku", "quantity", "unit_price"}] where unit_price is a string with exactly 2 decimals
      - total: string with exactly 2 decimals (sum(quantity * unit_price))

    Raises ValueError for invalid input.
    """
    try:
        model = InvoiceExportModel.parse_obj(data)
    except ValidationError as e:
        # Callers rely on ValueError semantics for invalid inputs.
        raise ValueError(str(e)) from e

    # Produce JSON with the exact required shapes/encodings.
    # Use BaseModel's JSON utilities for consistent formatting.
    # But we must ensure unit_price/total formatting is exact strings with 2 decimals.
    payload = model.export_dict()
    return BaseModel.parse_obj(payload).json()  # not suitable for exact structure typing

from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, List, Optional

from pydantic import BaseModel, Field, ValidationError
from pydantic import field_serializer
from pydantic_core import PydanticCustomError


class _Line(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Decimal = Field(..., ge=0)

    @field_serializer("unit_price")
    def _serialize_unit_price(self, v: Decimal) -> str:
        # Exact string with exactly two decimals
        q = Decimal("0.01")
        return str(v.quantize(q, rounding=ROUND_HALF_UP))


class _Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[_Line]

    @field_serializer("issued_at")
    def _serialize_issued_at(self, v: datetime) -> str:
        # naive datetimes are treated as UTC
        if v.tzinfo is None:
            v = v.replace(tzinfo=timezone.utc)
        else:
            v = v.astimezone(timezone.utc)
        # second precision + trailing Z
        v = v.replace(microsecond=0)
        return v.strftime("%Y-%m-%dT%H:%M:%SZ")

    def total_as_two_decimals(self) -> str:
        total = Decimal("0")
        for line in self.lines:
            total += (line.quantity * line.unit_price)
        return str(total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def export_invoice(data: dict) -> str:
    """
    Validate an invoice with pydantic and return its JSON text for the billing API.

    Input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive values are UTC)
      - lines: list of {sku: str, quantity: int>=1, unit_price: decimal>=0 as str/int/float}

    Output JSON:
      - number
      - issued_at formatted as YYYY-MM-DDTHH:MM:SSZ in UTC
      - lines: each with sku, quantity, unit_price as string with exactly two decimals
      - total: sum(quantity * unit_price) as string with exactly two decimals
    """
    try:
        inv = _Invoice.model_validate(data)
    except ValidationError as e:
        # Documented behavior: invalid input raises ValueError.
        raise ValueError(str(e)) from e

    out: dict[str, Any] = {
        "number": inv.number,
        "issued_at": _Invoice.__pydantic_serializer__.to_python(
            inv.issued_at, mode="json"
        ),
        "lines": [
            {"sku": line.sku, "quantity": line.quantity, "unit_price": _Line.__pydantic_serializer__.to_python(line.unit_price, mode="json")}
            for line in inv.lines
        ],
        "total": inv.total_as_two_decimals(),
    }

    # Ensure we match the billing API expectation: JSON text only.
    # Using BaseModel avoids pydantic v2 config json_encoders removal issues.
    # Here we just return standard JSON serialization of our dict.
    import json

    return json.dumps(out, separators=(",", ":"), ensure_ascii=False)

from __future__ import annotations

from typing import Any, Optional

from pydantic import BaseModel, ValidationError, field_validator


class _ImportedProfile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @field_validator("display_name")
    @classmethod
    def _clean_display_name(cls, v: str) -> str:
        v = " ".join(v.split())
        if not v:
            raise ValueError("display_name must not be blank")
        return v

    @field_validator("zip_code", mode="before")
    @classmethod
    def _zip_as_string(cls, v: Any) -> str:
        # Accept string or integer (and other int-like inputs that pydantic can coerce),
        # then store as a string.
        if v is None:
            raise ValueError("zip_code is required")
        return str(v)


def import_profiles(rows: list) -> list:
    """
    Validate profile rows (dicts from a CSV/JSON import) and return valid ones as dicts,
    in input order. Invalid rows are silently skipped.

    Each returned dict has keys:
      {"user_id": int, "display_name": str, "bio": str|None, "zip_code": str}
    """
    valid: list[dict[str, Any]] = []
    for row in rows:
        try:
            model = _ImportedProfile.model_validate(row)
        except ValidationError:
            continue

        valid.append(
            {
                "user_id": model.user_id,
                "display_name": model.display_name,
                "bio": model.bio,
                "zip_code": model.zip_code,
            }
        )
    return valid

from __future__ import annotations

import re
from typing import Any

from pydantic import BaseModel, Field, ValidationError, field_validator


_USERNAME_RE = re.compile(r"^[a-z0-9_]{3,20}$")
_PHONE_STRIP_RE = re.compile(r"[\s.\-()]")


class _SignupModel(BaseModel):
    username: str = Field(..., pattern=_USERNAME_RE.pattern)
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    @field_validator("email")
    @classmethod
    def _validate_email(cls, v: Any) -> str:
        if v is None:
            raise ValueError("email is required")
        if not isinstance(v, str):
            raise ValueError("email must be a string")
        cleaned = v.strip().lower()
        if "@" not in cleaned:
            raise ValueError('email must contain "@"')
        return cleaned

    @field_validator("phone")
    @classmethod
    def _validate_phone(cls, v: Any) -> str:
        if not isinstance(v, str):
            raise ValueError("phone must be a string")
        compact = _PHONE_STRIP_RE.sub("", v)
        if not re.fullmatch(r"\+\d{8,15}", compact):
            raise ValueError("invalid phone number")
        return compact

    @field_validator("password_confirm")
    @classmethod
    def _validate_password_confirm(cls, v: Any, info) -> str:
        # info.data contains already-validated fields in pydantic v2
        password = info.data.get("password")
        if v is None or password is None:
            # Missing fields will typically be caught by required fields,
            # but be defensive for custom errors.
            raise ValueError("password_confirm is required")
        if not isinstance(v, str):
            raise ValueError("password_confirm must be a string")
        if not isinstance(password, str):
            raise ValueError("password must be a string")
        if v != password:
            raise ValueError("passwords do not match")
        return v


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload and return:
      {"username": ..., "email": ..., "phone": <compact phone>}
    Raises ValueError if any field is missing or invalid.
    """
    try:
        model = _SignupModel.model_validate(data)
    except ValidationError as e:
        # Callers rely on pydantic ValidationError being acceptable as ValueError.
        # We re-raise to preserve pydantic's error details.
        raise e

    return {
        "username": model.username,
        "email": model.email,
        "phone": model.phone,
    }
